'use client';
import {FormEvent,useCallback,useEffect,useMemo,useState} from 'react';
import {LanguageSwitcher,localizedMessage,useLanguage} from '@/lib/i18n';
import {LoadingScreen} from '@/components/loading-screen';
import {NfcProgrammer} from '@/components/nfc-programmer';
import {DestinationEditor} from '@/components/destination-editor';
type Card={code:string;active:number;demo:number;activated_at:string|null;created_at:string;nfc:number;qr:number;nfc_registered_at:string|null};
type Stats={total:number;active:number;inactive:number;nfc:number;qr:number};
type Generated={code:string;activationCode:string;qrURL:string;nfcURL:string};
type ActivationCodes=Record<string,string>;
type Translate=(key:string)=>string;
const tabs=['overview','cards','analytics','flowPreview','settings'];
export function AdminPanel(){
 const {language,t}=useLanguage();
 const [username,setUsername]=useState(''),[password,setPassword]=useState(''),[showPassword,setShowPassword]=useState(false),[postLoginLoading,setPostLoginLoading]=useState(false),[logged,setLogged]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[stats,setStats]=useState<Stats|null>(null),[cards,setCards]=useState<Card[]>([]),[activationCodes,setActivationCodes]=useState<ActivationCodes>({}),[count,setCount]=useState(10),[generated,setGenerated]=useState<Generated[]>([]),[tab,setTab]=useState('overview'),[demo,setDemo]=useState(false),[notice,setNotice]=useState(''),[editDestination,setEditDestination]=useState<string|null>(null);
 const refresh=useCallback(async()=>{const [s,c,d,a]=await Promise.all([fetch('/api/admin/stats'),fetch('/api/admin/cards'),fetch('/api/demo/config'),fetch('/api/admin/cards/activation-codes')]);if(s.status===401||c.status===401){setLogged(false);return}if(!c.ok)throw new Error(t('dashboardLoadError'));setCards(await c.json());if(a.ok)setActivationCodes(await a.json());else setActivationCodes({});if(s.ok){setStats(await s.json());setError('')}else{setStats(null);setError(t('dashboardLoadError'))}if(d.ok)setDemo((await d.json()).demo);setLogged(true)},[t]);
 useEffect(()=>{refresh().catch(e=>setError(e.message))},[refresh]);
 async function login(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const r=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username,password})});const x=await r.json();if(!r.ok)throw new Error(localizedMessage(x.error||t('loginFailed'),language));setPassword('');setUsername('');setPostLoginLoading(true);await Promise.all([refresh(),new Promise(resolve=>window.setTimeout(resolve,700))])}catch(e){setError(e instanceof Error?localizedMessage(e.message,language):t('loginFailed'))}finally{setPostLoginLoading(false);setBusy(false)}}
 async function generate(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const r=await fetch('/api/admin/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({count})});const x=await r.json();if(!r.ok)throw new Error(localizedMessage(x.error||t('dashboardLoadError'),language));setGenerated(x.items);setNotice(x.notice);setTab('cards');await refresh()}catch(e){setError(e instanceof Error?localizedMessage(e.message,language):t('dashboardLoadError'))}finally{setBusy(false)}}
 async function reactivateCard(code:string){const prompt=language==='id'?`Aktivasi ulang ${code}? Kartu kembali nonaktif, review lama dilepas, dan kode aktivasi baru diterbitkan.`:`Reactivate ${code}? It returns to inactive, clears the old review URL, and issues a new activation code.`;if(!window.confirm(prompt))return;setBusy(true);setError('');try{const r=await fetch(`/api/admin/cards/${code}/reactivate`,{method:'POST'}),x=await r.json();if(!r.ok)throw new Error(x.error||t('dashboardLoadError'));setGenerated([]);setActivationCodes(prev=>({...prev,[code]:x.activationCode}));setNotice(language==='id'?`Kode baru untuk ${code} tersimpan dan tampil di tabel. Salin/cetak ulang untuk kartu.`:`A new code for ${code} is saved and shown in the table. Copy/reprint it for the card.`);await refresh()}catch(e){setError(e instanceof Error?e.message:t('dashboardLoadError'))}finally{setBusy(false)}}
 async function issueActivationCode(code:string){const prompt=language==='id'?`Buat sandi baru untuk ${code}? Kode lama menjadi tidak berlaku. Jika kode lama sudah dicetak, kartu perlu diberi sandi baru ini.`:`Issue a new code for ${code}? The old code becomes invalid. If it was printed, replace it with this new code.`;if(!window.confirm(prompt))return;setBusy(true);setError('');try{const r=await fetch(`/api/admin/cards/${code}/activation-code`,{method:'POST'}),x=await r.json();if(!r.ok)throw new Error(x.error||t('dashboardLoadError'));setActivationCodes(prev=>({...prev,[code]:x.activationCode}));setNotice(language==='id'?`Sandi baru untuk ${code} tersimpan dan tampil di kolom kode aktivasi.`:`The new code for ${code} is saved and shown in the activation-code column.`);await refresh()}catch(e){setError(e instanceof Error?e.message:t('dashboardLoadError'))}finally{setBusy(false)}}
 async function deleteCard(code:string){const prompt=language==='id'?`Hapus ${code} dari database? URL QR/NFC kartu akan berhenti berfungsi dan seluruh riwayat kunjungannya ikut dihapus.`:`Delete ${code} from the database? Its QR/NFC URL will stop working and all visit history will be deleted.`;if(!window.confirm(prompt))return;setBusy(true);setError('');try{const r=await fetch(`/api/admin/cards/${code}`,{method:'DELETE'}),x=await r.json();if(!r.ok)throw new Error(x.error||t('dashboardLoadError'));setGenerated([]);setNotice(language==='id'?`${code} dan riwayat kunjungannya telah dihapus dari database.`:`${code} and its visit history were deleted from the database.`);await refresh()}catch(e){setError(e instanceof Error?e.message:t('dashboardLoadError'))}finally{setBusy(false)}}
 const csv=useMemo(()=>{if(!generated.length)return '';const rows=[[t('cardId'),t('activationCode'),t('qrUrl'),t('nfcUrl')],...generated.map(x=>[x.code,x.activationCode,x.qrURL,x.nfcURL])];return rows.map(row=>row.map(v=>{const safe=/^[=+@-]/.test(v)?`'${v}`:v;return `"${safe.replaceAll('"','""')}"`}).join(',')).join('\r\n')},[generated,t]);
 function downloadCsv(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='repiw-cards.csv';a.click();URL.revokeObjectURL(a.href)}
 async function doLogout(){await fetch('/api/logout',{method:'POST'});setLogged(false);setStats(null);setActivationCodes({});setGenerated([])}
 async function demoAction(action:'seed'|'reset'){setBusy(true);setError('');try{const r=await fetch(`/api/demo/${action}`,{method:'POST'}),x=await r.json();if(!r.ok)throw new Error(localizedMessage(x.error||t('startDemoError'),language));if(action==='seed'){setGenerated(x.inactiveCards.map((c:{code:string;activationCode:string})=>({code:c.code,activationCode:c.activationCode,qrURL:`${location.origin}/c/${c.code}?src=qr`,nfcURL:`${location.origin}/c/${c.code}?src=nfc`})));setNotice(t('demoReady'))}else{setGenerated([]);setNotice(t('demoReset'))}await refresh()}catch(e){setError(e instanceof Error?localizedMessage(e.message,language):t('startDemoError'))}finally{setBusy(false)}}
 if(postLoginLoading)return <LoadingScreen message={t('loadingDashboard')}/>;
 if(!logged)return <main className="activation-shell login-shell"><div className="auth-language"><LanguageSwitcher/></div><section className="login-story"><a className="brand login-brand" href="/">repiw<span>.</span></a><p className="eyebrow">{t('featureChannels')}</p><h2>{t('heroTitle')}</h2><p className="login-story-copy">{t('heroDescription')}</p><div className="login-points"><div><i>01</i><span>{t('featureActivation')}</span></div><div><i>02</i><span>{t('featureChannels')}</span></div><div><i>03</i><span>{t('featureInsights')}</span></div></div><div className="login-art" aria-hidden="true"><div className="login-art-ring ring-a"/><div className="login-art-ring ring-b"/><div className="login-art-card"><span>repiw<span>.</span></span><i>)))</i><b>REVIEW CARD</b></div></div></section><form className="activation-card login-card" onSubmit={login}><div className="brand-mark">R</div><p className="eyebrow">{t('secureAccess')}</p><h1>{t('welcome')}</h1><p className="muted">{t('signInDescription')}</p><label>{t('username')}<input autoFocus type="text" value={username} onChange={e=>setUsername(e.target.value)} autoComplete="username" required/></label><label>{t('adminPassword')}<span className="password-field"><input type={showPassword?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required/><button type="button" className="password-toggle" aria-label={t(showPassword?'hidePassword':'showPassword')} onClick={()=>setShowPassword(v=>!v)}>{showPassword?'◉':'◎'}</button></span></label>{error&&<p className="error login-error" role="alert">{error}</p>}<button className="login-submit" disabled={busy}>{busy?t('signingIn'):t('signIn')}<span aria-hidden="true">→</span></button><a className="text-link centered" href="/flow-preview">{t('exploreFlow')}</a><p className="login-footnote">{t('privateWorkspace')}</p></form></main>;
 const icons:Record<string,string>={overview:'◫',cards:'▣',analytics:'⌁',flowPreview:'▷',settings:'⚙'};
 return <div className="dashboard"><aside className="sidebar"><a className="brand" href="/">repiw<span>.</span></a><p className="side-label">{t('workspace')}</p><nav>{tabs.map(n=><button className={tab===n?'nav-item selected':'nav-item'} key={n} onClick={()=>n==='flowPreview'?location.assign('/flow-preview'):setTab(n)}><i>{icons[n]}</i>{t(n)}</button>)}</nav><div className="side-bottom"><div className="avatar">A</div><div><b>Admin</b><small>{demo?t('demoWorkspace'):'REPIW'}</small></div><button className="icon-button" onClick={doLogout} aria-label={t('signOut')}>↗</button></div></aside><main className="dash-content"><header className="dash-top"><div className="mobile-brand brand">repiw<span>.</span></div><div className="dash-heading"><p className="eyebrow">{demo?t('demoWorkspace').toUpperCase():t('cardManagement')}</p><h1>{tab==='overview'?t('goodToSeeYou'):t(tab)}</h1></div><div className="dash-actions"><LanguageSwitcher/><button className="button button-outline" onClick={()=>refresh().catch(e=>setError(e.message))}>↻ <span className="desktop-only">{t('refresh')}</span></button><button className="button button-outline mobile-logout" onClick={doLogout}>{t('signOut')}</button></div></header><nav className="mobile-nav" aria-label={t('workspace')}>{tabs.map(n=><button key={n} className={tab===n?'mobile-nav-item selected':'mobile-nav-item'} aria-current={tab===n?'page':undefined} onClick={()=>n==='flowPreview'?location.assign('/flow-preview'):setTab(n)}>{t(n)}</button>)}</nav>{error&&<p className="error banner">{error}</p>}{notice&&<p className="success banner">{notice}<button className="dismiss" onClick={()=>setNotice('')}>×</button></p>}
 {tab==='overview'&&<><p className="muted intro">{t('happening')}</p><section className="metrics"><Metric title={t('totalCards')} value={stats?.total}/><Metric title={t('activeCards')} value={stats?.active} tone="green"/><Metric title={t('inactiveCards')} value={stats?.inactive}/><Metric title={t('nfcTaps')} value={stats?.nfc} tone="violet"/><Metric title={t('qrScans')} value={stats?.qr} tone="blue"/></section><div className="dash-grid"><section className="panel"><div className="panel-head"><div><p className="eyebrow">{t('recentActivity')}</p><h2>{t('latestCards')}</h2></div><button className="text-link" onClick={()=>setTab('cards')}>{t('viewAll')}</button></div><CardTable cards={cards.slice(0,6)} t={t} language={language} activationCodes={activationCodes}/></section><section className="panel generate-panel"><p className="eyebrow">{t('getStarted')}</p><h2>{t('generateCards')}</h2><p className="muted">{t('createUnique')}</p><GenerateForm count={count} setCount={setCount} busy={busy} onSubmit={generate} t={t}/><a className="text-link" href="/flow-preview">{t('previewEveryStep')}</a></section></div></>}
 {tab==='cards'&&<><div className="panel toolbar"><div><p className="eyebrow">{t('cardLibrary')}</p><h2>{cards.length} {t('cards').toLowerCase()}</h2></div><div className="toolbar-actions"><a className="button button-outline" href="/api/admin/qr-zip">{t('downloadQrZip')}</a><button className="button" onClick={()=>setTab('overview')}>{t('generateMore')}</button></div></div><NfcProgrammer cards={cards} onComplete={refresh} language={language}/>{generated.length>0&&<GeneratedTable items={generated} csv={downloadCsv} t={t}/>}{editDestination&&<DestinationEditor code={editDestination} onSaved={msg=>{setNotice(msg);setEditDestination(null);refresh().catch(e=>setError(e.message))}} onClose={()=>setEditDestination(null)}/>}<section className="panel"><CardTable cards={cards} t={t} language={language} activationCodes={activationCodes} allowActions onReactivate={reactivateCard} onDelete={deleteCard} onIssueCode={issueActivationCode} onEditDestination={setEditDestination} busy={busy}/></section></>}
 {tab==='analytics'&&<section className="metrics analytics-metrics"><Metric title={t('totalCards')} value={stats?.total}/><Metric title={t('activeCards')} value={stats?.active} tone="green"/><Metric title={t('inactiveCards')} value={stats?.inactive}/><Metric title={t('visitsNfc')} value={stats?.nfc} tone="violet"/><Metric title={t('visitsQr')} value={stats?.qr} tone="blue"/></section>}
 {tab==='settings'&&<section className="panel settings-panel"><p className="eyebrow">{t('workspaceSettings')}</p><h2>{t('environment')}</h2><p className="muted">{demo?t('demoModeOn'):t('productionMode')}</p><div className="language-setting"><b>{t('languageSetting')}</b><LanguageSwitcher/></div>{demo&&<div className="settings-actions"><button className="button" disabled={busy} onClick={()=>demoAction('seed')}>{t('seedDemo')}</button><button className="button button-outline" disabled={busy} onClick={()=>demoAction('reset')}>{t('resetDemo')}</button></div>}<a href="/flow-preview" className="text-link">{t('openFlow')}</a></section>}
 </main></div>;
}
function Metric({title,value,tone=''}:{title:string;value?:number;tone?:string}){return <article className="metric"><div className={`metric-icon ${tone}`}>◦</div><p>{title}</p><strong>{(value??0).toLocaleString()}</strong></article>}
function GenerateForm({count,setCount,busy,onSubmit,t}:{count:number;setCount:(n:number)=>void;busy:boolean;onSubmit:(e:FormEvent)=>void;t:Translate}){return <form className="generate-form" onSubmit={onSubmit}><label>{t('numberOfCards')}<select value={count} onChange={e=>setCount(Number(e.target.value))}>{[10,25,50,100].map(n=><option key={n}>{n}</option>)}</select></label><button disabled={busy}>{t('generateCardsButton')} <span>→</span></button></form>}
function CardTable({cards,t,language,activationCodes,allowActions=false,onReactivate,onDelete,onIssueCode,onEditDestination,busy=false}:{cards:Card[];t:Translate;language:'id'|'en';activationCodes:ActivationCodes;allowActions?:boolean;onReactivate?:(code:string)=>void;onDelete?:(code:string)=>void;onIssueCode?:(code:string)=>void;onEditDestination?:(code:string)=>void;busy?:boolean}){return <div className="table-wrap"><table><thead><tr><th>{t('cardId')}</th><th>{language==='id'?'Kode Aktivasi':'Activation Code'}</th><th>Status</th><th>{t('activatedDate')}</th><th>NFC</th><th>QR</th><th>{t('qrFile')}</th>{allowActions&&<th>{language==='id'?'Aksi':'Actions'}</th>}</tr></thead><tbody>{cards.map(c=><tr key={c.code}><td><b>{c.code}</b>{c.demo===1&&<small className="demo-tag">DEMO</small>}</td><td>{!c.active&&activationCodes[c.code]?<code className="activation-code-cell">{activationCodes[c.code]}</code>:!c.active?'—':'—'}</td><td><span className={c.active?'status active':'status inactive'}><i/>{c.active?t('activated'):t('inactiveCards')}</span></td><td>{c.activated_at?new Date(c.activated_at+'Z').toLocaleDateString(language==='id'?'id-ID':'en-US'):'—'}</td><td>{c.nfc}</td><td>{c.qr}</td><td><a className="download-link" href={`/api/admin/qr/${c.code}`}>{t('downloadPng')}</a></td>{allowActions&&<td><div className="card-actions">{c.active&&onEditDestination&&<button className="button button-outline destination-edit" disabled={busy} onClick={()=>onEditDestination(c.code)}>{language==='id'?'Ubah tujuan':'Change destination'}</button>}{c.active&&<button className="button button-outline" disabled={busy} onClick={()=>onReactivate?.(c.code)}>{language==='id'?'Aktifkan ulang':'Reactivate'}</button>}{!c.active&&!activationCodes[c.code]&&<button className="button button-outline" disabled={busy} onClick={()=>onIssueCode?.(c.code)}>{language==='id'?'Buat sandi':'Issue code'}</button>}<button className="button button-danger" disabled={busy} onClick={()=>onDelete?.(c.code)}>{language==='id'?'Hapus':'Delete'}</button></div></td>}</tr>)}</tbody></table>{!cards.length&&<p className="empty">{t('noCards')}</p>}</div>}
function GeneratedTable({items,csv,t}:{items:Generated[];csv:()=>void;t:Translate}){return <section className="panel generated"><div className="panel-head"><div><p className="eyebrow">{t('newBatch')}</p><h2>{items.length} {t('cardsGenerated')}</h2><p className="warning">{t('activationCodesOnce')}</p></div><button className="button" onClick={csv}>{t('downloadCsv')}</button></div><div className="table-wrap"><table><thead><tr><th>{t('cardId')}</th><th>{t('activationCode')}</th><th>{t('qrUrl')}</th><th>{t('nfcUrl')}</th></tr></thead><tbody>{items.map(i=><tr key={i.code}><td><b>{i.code}</b></td><td><code>{i.activationCode}</code></td><td><a href={i.qrURL} target="_blank">{t('qrLink')}</a></td><td><a href={i.nfcURL} target="_blank">{t('nfcLink')}</a></td></tr>)}</tbody></table></div></section>}
